settings.liquid:
{% assign bandeau = product.metafields.custom.bandeau_caracteristiques.value %}

{% if bandeau != blank %}
<style>
  .badges-wrap * { box-sizing: border-box; margin: 0; padding: 0; }
  .badges-wrap {
    font-family: 'Poppins', sans-serif;
    padding: 0 0 0px;
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
  }
  .badge-item {
    background: #1a4fab;
    color: #fff;
    font-size: 13px;
    font-weight: 500;
    padding: 7px 16px;
    border-radius: 20px;
    display: inline-block;
  }
</style>

<div class="badges-wrap">
  {% if bandeau.nom_du_produit != blank %}
    <span class="badge-item">{{ bandeau.nom_du_produit }}</span>
  {% endif %}
  {% if bandeau.titres_2 != blank %}
    <span class="badge-item">{{ bandeau.titres_2 }}</span>
  {% endif %}
  {% if bandeau.titre_3 != blank %}
    <span class="badge-item">{{ bandeau.titre_3 }}</span>
  {% endif %}
</div>

{% endif %}
